from pathlib import Path

p = Path('src/local_coop_mobile.cc')
s = p.read_text(encoding='utf-8')
marker = '// PHOBOI_VIDEO_LAYOUT_V4'
if marker in s:
    print('PhoBoi video/layout v4 already applied')
    raise SystemExit(0)

old_css = '''*{box-sizing:border-box;touch-action:none}body{margin:0;background:#07100b;color:#9cff9c;font-family:monospace;overflow:hidden}\n#join{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#07100b;z-index:5}\n.panel{border:2px solid #4dbd68;padding:20px;width:min(92vw,420px);box-shadow:0 0 28px #174d29}\nh1{margin:0 0 14px;font-size:25px}.row{display:flex;gap:8px;margin-top:10px}input,select,button{font:inherit;color:#d7ffd7;background:#102218;border:1px solid #4dbd68;padding:12px}\ninput{width:100%}select{flex:1}button{font-weight:bold}.status{height:22px;margin-top:10px;color:#ffd56a}\n#pad{display:none;position:fixed;inset:0;background:radial-gradient(circle at center,#183321,#07100b)}#video{position:absolute;left:18vw;top:3vh;width:64vw;height:55vh;object-fit:contain;background:#000;border:1px solid #295f37;image-rendering:auto}\n.top{position:absolute;left:0;right:0;top:7px;text-align:center;font-size:13px}\n.control-label{display:block;font-size:9px;line-height:1.05;color:#bfffc8;font-weight:normal;margin-top:2px;white-space:normal}\n.stick-label{position:absolute;left:50%;top:8%;transform:translateX(-50%);z-index:2;font-size:10px;line-height:1.05;text-align:center;color:#d7ffd7;background:#07100bcc;padding:3px 6px;border:1px solid #3a8d4d;border-radius:6px;pointer-events:none}\n.stick{position:absolute;width:31vw;height:31vw;max-width:220px;max-height:220px;border:3px solid #4dbd68;border-radius:50%;background:#0b1c11aa}\n#ls{left:5vw;bottom:8vh}#rs{right:31vw;bottom:8vh}.nub{position:absolute;width:38%;height:38%;left:31%;top:31%;border-radius:50%;background:#68dd82}\n.btn{position:absolute;border-radius:50%;width:14vw;height:14vw;max-width:88px;max-height:88px;padding:0;background:#173923cc}\n#ba{right:5vw;bottom:18vh}#bb{right:17vw;bottom:7vh}#bx{right:17vw;bottom:29vh}#by{right:29vw;bottom:18vh}\n.small{width:11vw;height:9vw;max-width:74px;max-height:54px;border-radius:10px}\n#lb{left:4vw;top:7vh}#lt{left:17vw;top:7vh}#rb{right:17vw;top:7vh}#rt{right:4vw;top:7vh}\n#back{left:39vw;top:12vh}#start{right:39vw;top:12vh}#skill{left:44.5vw;top:22vh;width:11vw}\n.dpad{position:absolute;left:39vw;bottom:34vh;display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(3,44px)}\n.dpad button{padding:0}.du{grid-column:2}.dl{grid-column:1;grid-row:2}.dr{grid-column:3;grid-row:2}.dd{grid-column:2;grid-row:3}\n@media (orientation:portrait){#rs{right:5vw;bottom:31vh}.dpad{left:36vw;bottom:45vh}#ba{bottom:17vh}#bx{bottom:29vh}}\n'''
new_css = '''/* PHOBOI_VIDEO_LAYOUT_V4 */\n*{box-sizing:border-box;touch-action:none;-webkit-user-select:none;user-select:none}\nhtml,body{width:100%;height:100%;margin:0;overflow:hidden;background:#07100b;color:#9cff9c;font-family:monospace}\nbody{min-height:100dvh}\n#join{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#07100b;z-index:20;padding:max(12px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left))}\n.panel{border:2px solid #4dbd68;padding:20px;width:min(92vw,420px);box-shadow:0 0 28px #174d29}\nh1{margin:0 0 14px;font-size:25px}.row{display:flex;gap:8px;margin-top:10px}input,select,button{font:inherit;color:#d7ffd7;background:#102218;border:1px solid #4dbd68;padding:10px}\ninput{width:100%}select{flex:1}button{font-weight:bold}.status{min-height:22px;margin-top:10px;color:#ffd56a}\n#pad{display:none;position:fixed;inset:0;padding:calc(env(safe-area-inset-top) + 4px) calc(env(safe-area-inset-right) + 6px) calc(env(safe-area-inset-bottom) + 6px) calc(env(safe-area-inset-left) + 6px);background:radial-gradient(circle at center,#183321,#07100b);overflow:hidden}\n#video{position:absolute;left:25%;top:28px;width:50%;height:44%;object-fit:contain;background:#000;border:1px solid #295f37;image-rendering:auto;z-index:1}\n.top{position:absolute;left:22%;right:22%;top:5px;text-align:center;font-size:clamp(9px,1.8vw,13px);z-index:4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.control-label{display:block;font-size:clamp(6px,1.15vw,9px);line-height:1;color:#bfffc8;font-weight:normal;margin-top:1px;white-space:normal;pointer-events:none}\n.stick-label{position:absolute;left:50%;top:8%;transform:translateX(-50%);z-index:2;font-size:clamp(7px,1.2vw,10px);line-height:1.05;text-align:center;color:#d7ffd7;background:#07100bcc;padding:2px 4px;border:1px solid #3a8d4d;border-radius:5px;pointer-events:none}\n.stick{position:absolute;width:clamp(112px,22vmin,190px);height:clamp(112px,22vmin,190px);border:3px solid #4dbd68;border-radius:50%;background:#0b1c11dd;bottom:max(10px,env(safe-area-inset-bottom));z-index:5}\n#ls{left:max(10px,env(safe-area-inset-left))}#rs{right:calc(max(10px,env(safe-area-inset-right)) + clamp(150px,29vmin,235px))}.nub{position:absolute;width:38%;height:38%;left:31%;top:31%;border-radius:50%;background:#68dd82}\n.btn{position:absolute;border-radius:50%;width:clamp(48px,10vmin,76px);height:clamp(48px,10vmin,76px);padding:2px;background:#173923ee;z-index:6}\n#ba{right:max(8px,env(safe-area-inset-right));bottom:clamp(58px,12vmin,92px)}\n#bb{right:clamp(62px,13vmin,102px);bottom:max(6px,env(safe-area-inset-bottom))}\n#bx{right:clamp(62px,13vmin,102px);bottom:clamp(116px,24vmin,184px)}\n#by{right:clamp(116px,24vmin,184px);bottom:clamp(58px,12vmin,92px)}\n.small{position:absolute;width:clamp(54px,9vw,82px);height:clamp(36px,7vmin,52px);border-radius:9px;padding:2px;z-index:6}\n#lb{left:max(8px,env(safe-area-inset-left));top:6px}#lt{left:clamp(68px,11vw,110px);top:6px}#rb{right:clamp(68px,11vw,110px);top:6px}#rt{right:max(8px,env(safe-area-inset-right));top:6px}\n#back{left:calc(50% - 118px);top:calc(44% + 34px)}#start{right:calc(50% - 118px);top:calc(44% + 34px)}#skill{left:calc(50% - 38px);top:calc(44% + 82px);width:76px}\n.dpad{position:absolute;left:calc(50% - 66px);bottom:max(8px,env(safe-area-inset-bottom));display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(3,42px);gap:2px;z-index:6}\n.dpad button{padding:1px;min-width:0;min-height:0}.du{grid-column:2}.dl{grid-column:1;grid-row:2}.dr{grid-column:3;grid-row:2}.dd{grid-column:2;grid-row:3}\n@media (max-height:430px){#video{top:24px;height:39%;width:44%;left:28%}#back,#start{top:calc(39% + 28px)}#skill{top:calc(39% + 68px)}.stick{width:clamp(104px,25vh,150px);height:clamp(104px,25vh,150px)}#rs{right:calc(max(8px,env(safe-area-inset-right)) + 150px)}.btn{width:54px;height:54px}#ba{bottom:58px}#bb{right:62px}#bx{right:62px;bottom:116px}#by{right:116px;bottom:58px}.dpad{grid-template-columns:repeat(3,36px);grid-template-rows:repeat(3,36px);left:calc(50% - 56px)}}\n@media (orientation:portrait){#pad:before{content:'ROTATE PHONE TO LANDSCAPE';position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#07100b;color:#ffd56a;font-size:18px;z-index:15}#video,.stick,.btn,.small,.dpad,.top{visibility:hidden}}\n'''
if old_css not in s:
    raise SystemExit('mobile CSS block not found')
s = s.replace(old_css, new_css, 1)

old_capture = '''void mobileCaptureStreamFrame(uint64_t now)\n{\n    if (gSdlSurface == nullptr) return;\n'''
new_capture = '''void mobileCaptureStreamFrame(uint64_t now)\n{\n    // PHOBOI_VIDEO_LAYOUT_V4\n    // Capture the RGB staging surface that is actually uploaded to the SDL\n    // renderer. gSdlSurface is the old 8-bit indexed framebuffer and can yield\n    // black/incorrect remote frames depending on palette/conversion timing.\n    SDL_Surface* captureSurface = gSdlTextureSurface;\n    if (captureSurface == nullptr) return;\n'''
if old_capture not in s:
    raise SystemExit('mobile capture function anchor not found')
s = s.replace(old_capture, new_capture, 1)

old_blit = '''    if (SDL_BlitScaled(gSdlSurface, nullptr, scaled, &dst) != 0) {\n'''
new_blit = '''    if (SDL_BlitScaled(captureSurface, nullptr, scaled, &dst) != 0) {\n'''
if old_blit not in s:
    raise SystemExit('mobile capture blit anchor not found')
s = s.replace(old_blit, new_blit, 1)

# Don't attempt the highest remote tier until the browser has proven it is\n# receiving control packets reliably. This reduces initial bandwidth spikes and\n# gives the first visible frame a much better chance over tunnels/mobile data.
s = s.replace('''    int width = 480;\n    int height = 270;\n    int fps = 12;\n    if (worstRtt <= 45 && worstJitter <= 12 && worstInterval <= 24) {\n        width = 1280; height = 720; fps = 30;\n''', '''    int width = 480;\n    int height = 270;\n    int fps = 12;\n    if (worstRtt <= 45 && worstJitter <= 12 && worstInterval <= 24) {\n        width = 960; height = 540; fps = 24;\n''', 1)

p.write_text(s, encoding='utf-8')
print('PhoBoi video source + responsive landscape layout v4 applied')
